"""Alembic migrations are derived artifacts: autogenerated in the sandbox from the models, never written by the LLM.

The migration is regenerated only when the model files changed since the last generation, so repairs that touch
the models get a fresh migration and everything else keeps a stable file.
"""

import hashlib
import json
import re
from pathlib import Path
from typing import Any

from src.sandbox import ExecResult, ISandbox

MODEL_SOURCES = (
    "src/modules/shared/infrastructure/models",
    "src/modules/shared/domain/entities",
    "src/modules/__init__.py",
)
STATE_FILE = ".bga/migration.json"
VERSIONS_DIR = "alembic/versions"
SCHEMA_MARKER = "BGA_SCHEMA_BEGIN"
END_MARKER = "    # ### end Alembic commands ###"
ENUM_NAME = re.compile(r"sa\.Enum\([^)]*?name=['\"]([A-Za-z0-9_]+)['\"]")


def models_hash(project: Path) -> str:
    digest = hashlib.sha256()
    for relative in MODEL_SOURCES:
        path = project / relative
        files = sorted(path.rglob("*.py")) if path.is_dir() else [path] if path.is_file() else []
        for file in files:
            if "__pycache__" in file.parts:
                continue
            digest.update(file.relative_to(project).as_posix().encode())
            digest.update(file.read_bytes())
    return digest.hexdigest()


def add_enum_drops(migration: str) -> str:
    """Autogenerate never drops PostgreSQL enum types on downgrade, so `downgrade base` + `upgrade head` fails
    with "type already exists". Append the drops (idempotent: skipped when already present)."""
    head, separator, downgrade = migration.partition("def downgrade")
    if not separator:
        return migration
    names = [name for name in dict.fromkeys(ENUM_NAME.findall(head)) if f"name='{name}').drop" not in downgrade]
    if not names:
        return migration
    drops = "".join(f"    sa.Enum(name='{name}').drop(op.get_bind(), checkfirst=True)\n" for name in names)
    if END_MARKER in downgrade:
        position = downgrade.rindex(END_MARKER)
        downgrade = downgrade[:position] + drops + downgrade[position:]
    else:
        downgrade = downgrade.rstrip("\n") + "\n" + drops
    return head + separator + downgrade


def _versions(project: Path) -> list[Path]:
    return sorted((project / VERSIONS_DIR).glob("*.py"))


async def ensure_migration(sandbox: ISandbox, project: Path) -> tuple[ExecResult | None, bool]:
    """Regenerates `alembic/versions/*_initial_schema.py` when the models changed.

    Returns (autogenerate result or None when nothing changed, regenerated?)."""
    state_path = project / STATE_FILE
    current = models_hash(project)
    state = json.loads(state_path.read_text()) if state_path.exists() else {}
    if state.get("modelsHash") == current and _versions(project):
        return None, False
    for path in _versions(project):
        path.unlink()
    await sandbox.reset_database("app")
    result = await sandbox.exec('alembic revision --autogenerate -m "initial_schema"', timeout_s=120)
    if result.ok:
        for path in _versions(project):
            path.write_text(add_enum_drops(path.read_text()))
        state_path.parent.mkdir(parents=True, exist_ok=True)
        state_path.write_text(json.dumps({"modelsHash": current}) + "\n")
    return result, True


async def verify_migration(sandbox: ISandbox) -> ExecResult:
    """Fresh database: upgrade, no drift, full downgrade, upgrade again (leaves the schema at head)."""
    await sandbox.reset_database("app")
    return await sandbox.exec(
        "set -e; alembic upgrade head; alembic check; alembic downgrade base; alembic upgrade head", timeout_s=180
    )


async def reflect_schema(sandbox: ISandbox) -> tuple[dict[str, Any] | None, ExecResult]:
    result = await sandbox.exec("python /opt/bga/bin/reflect_schema.py", timeout_s=60)
    if not result.ok or SCHEMA_MARKER not in result.stdout:
        return None, result
    payload = result.stdout.split(SCHEMA_MARKER, 1)[1].strip()
    try:
        return json.loads(payload), result
    except json.JSONDecodeError:
        return None, result
